    <header class="matrix-header">
        <div>
            <span class="eyebrow">访问治理</span>
            <h1>项目空间权限</h1>
            <p>按角色和资源维护最小权限集合</p>
        </div>
        <div class="header-actions">
            <button type="button" class="secondary">查看审计</button>
            <button type="button" disabled="true">保存变更</button>
        </div>
    </header>
    <section class="matrix-stats">
        <article>
            <span>已授权单元</span>
            <strong>10</strong>
        </article>
        <article>
            <span>授权覆盖率</span>
            <strong>67</strong>%
        </article>
        <article>
            <span>当前角色</span>
            <strong>管理员</strong>
        </article>
    </section>
    <section class="matrix-toolbar">
        <label>
            筛选资源
            <input placeholder="名称或分组" value="" />
        </label>
        <div class="role-tabs">
            <button type="button" s-for="role, index in roles trackby role.id"></button>
        </div>
        <button type="button" class="secondary">当前角色全选</button>
        <button type="button" class="secondary">当前角色清空</button>
    </section>
    <section class="matrix-shell">
        <table>
            <thead>
                <tr>
                    <th>资源</th>
                    <th s-for="role, index in roles trackby role.id">
                        <span></span>
                        <button type="button">整列切换</button>
                    </th>
                    <th>批量</th>
                </tr>
            </thead>
            <tbody>
                <tr s-for="row, rowIndex in matrixRows trackby row.id">
                    <th>
                        <strong></strong>
                        <small></small>
                    </th>
                    <td s-for="cell, cellIndex in row.cells trackby cell.roleId">
                        <button type="button" class="grant-cell "></button>
                    </td>
                    <td>
                        <button type="button" class="row-toggle">整行切换</button>
                    </td>
                </tr>
            </tbody>
        </table>
        
    </section>
    
    <footer class="matrix-footer">
        <span>所有更改已保存</span>
        <span>最近保存：尚未保存</span>
    </footer>
</main>
